//! OUTPUT replacement reaches actual text paint and native interaction.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn output_text_replacement_actual_app_updates_text_paint_and_preserves_interaction(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-output-text-replacement-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}output{display:block;position:absolute;left:20px;top:20px;width:120px;height:32px;background:white;color:#112233}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}label{position:absolute;left:20px;top:100px}</style><body><form id=owner><label id=label for=output>Result</label><output id=output for=seed name=result><span>WWWW</span></output></form><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Change result</button><div id=destination></div><script>var output=document.getElementById('output'),labels=output.labels,tokens=output.htmlFor,classes=output.classList,round=0;document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'native pointer event';var value=round===1?'':round===0?'IIII':'MMMM',old=output.firstChild,watch=new MutationObserver(function(){});watch.observe(output,{childList:true});if(round===0)output.textContent=value;else if(round===1)output.textContent=null;else Object.getOwnPropertyDescriptor(Node.prototype,'textContent').set.call(output,value);var records=watch.takeRecords();if(output.textContent!==value||output.childNodes.length!==(round===1?0:1)||old!==null&&old.parentNode!==null||records.length!==1||records[0].target!==output||records[0].removedNodes.length!==(round===2?0:1)||records[0].addedNodes.length!==(round===1?0:1)||round!==1&&records[0].addedNodes[0]!==output.firstChild||output.labels!==labels||labels[0].control!==output||output.htmlFor!==tokens||tokens.value!=='seed'||output.classList!==classes||output.name!=='result'||output.form!==document.getElementById('owner'))throw 'actual replacement and native associations';watch.disconnect();document.title='Output text '+round;round++;};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);let initial=app.draw();let top=app.content_top() as usize;let patch=|pixels:&[u32],width:usize|{let mut result=Vec::new();for y in top+20..top+52{result.extend_from_slice(&pixels[y*width+20..y*width+140]);}result};let mut previous=patch(&initial.pixels,initial.width);assert!(previous.iter().any(|pixel|*pixel!=0xffffff));
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;
 for round in 0..3{let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,format!("Output text {round}"));let painted=app.draw();let current=patch(&painted.pixels,painted.width);assert_ne!(current,previous,"actual text pixels must change");assert_eq!(current.iter().all(|pixel|*pixel==0xffffff),round==1);previous=current;let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);}
}
